package com.mariyamrpt.seer_aii.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.SecurityFilterChain; import org.springframework.web.cors.*; import java.util.List;
@Configuration public class SecurityConfig {
 @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(cors())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/**","/","/index.html","/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().permitAll()).headers(h->h.contentSecurityPolicy(p->p.policyDirectives("default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'"))).build();}
 @Bean CorsConfigurationSource cors(){CorsConfiguration c=new CorsConfiguration(); c.setAllowedOriginPatterns(List.of("chrome-extension://*","http://127.0.0.1:[*]","http://localhost:[*]")); c.setAllowedMethods(List.of("GET","POST","PUT","OPTIONS")); c.setAllowedHeaders(List.of("Content-Type","X-SEER-PAIRING-TOKEN")); UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource(); s.registerCorsConfiguration("/api/**",c); return s;}
}
